pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title Bus
 * @dev A smart contract to simulate a bus service.
 * The owner of the contract can set the fare and capacity, start and end trips,
 * and withdraw the collected funds. Passengers can buy tickets for the current
 * trip before it starts.
 */
contract Bus is Ownable, ReentrancyGuard {
    /**
     * @dev Represents the current operational state of the bus.
     * A bus is either `Stopped` (boarding passengers) or `InProgress` (en route).
     */
    enum TripStatus {
        Stopped,
        InProgress
    }

    /// @dev The price of a single ticket in wei.
    uint256 public fare;

    /// @dev The maximum number of passengers the bus can hold.
    uint256 public capacity;

    /// @dev A unique identifier for each trip, incremented after a trip ends.
    uint256 public currentTripId;

    /// @dev The current status of the trip (Stopped or InProgress).
    TripStatus public currentTripStatus;

    /// @dev Mapping from trip ID to the number of passengers for that trip.
    mapping(uint256 => uint256) public passengerCountPerTrip;

    /// @dev Mapping from trip ID to passenger address to boolean, indicating if a ticket was purchased.
    mapping(uint256 => mapping(address => bool)) public hasTicketForTrip;

    /// @dev Emitted when the owner updates the ticket fare.
    event FareUpdated(uint256 newFare);

    /// @dev Emitted when the owner updates the bus capacity.
    event CapacityUpdated(uint256 newCapacity);

    /// @dev Emitted when a passenger successfully buys a ticket.
    event TicketPurchased(uint256 indexed tripId, address indexed passenger);

    /// @dev Emitted when the owner starts a trip.
    event TripStarted(uint256 indexed tripId);

    /// @dev Emitted when the owner ends a trip.
    event TripEnded(uint256 indexed tripId, uint256 passengerCount);

    /// @dev Emitted when the owner withdraws funds from the contract.
    event FundsWithdrawn(address indexed owner, uint256 amount);

    /**
     * @dev Initializes the contract, setting the deployer as the owner.
     * The first trip ID is set to 1 and the bus is initially stopped.
     */
    constructor() {
        currentTripId = 1;
        currentTripStatus = TripStatus.Stopped;
    }

    /**
     * @dev Allows the owner to set the fare for a ticket.
     * @param _newFare The new price of a ticket in wei. Must be greater than 0.
     */
    function setFare(uint256 _newFare) external onlyOwner {
        require(_newFare > 0, "Bus: Fare must be greater than zero");
        fare = _newFare;
        emit FareUpdated(_newFare);
    }

    /**
     * @dev Allows the owner to set the maximum capacity of the bus.
     * @param _newCapacity The new maximum number of passengers. Must be greater than 0.
     */
    function setCapacity(uint256 _newCapacity) external onlyOwner {
        require(_newCapacity > 0, "Bus: Capacity must be greater than zero");
        capacity = _newCapacity;
        emit CapacityUpdated(_newCapacity);
    }

    /**
     * @dev Allows a passenger to buy a ticket for the current trip.
     * Reverts if the trip is in progress, fare is not set, payment is incorrect,
     * the bus is full, or the passenger has already bought a ticket for this trip.
     */
    function buyTicket() external payable nonReentrant {
        require(currentTripStatus == TripStatus.Stopped, "Bus: Trip is in progress");
        require(fare > 0, "Bus: Fare has not been set");
        require(capacity > 0, "Bus: Capacity has not been set");
        require(msg.value == fare, "Bus: Incorrect fare paid");
        require(passengerCountPerTrip[currentTripId] < capacity, "Bus: Bus is full");
        require(!hasTicketForTrip[currentTripId][msg.sender], "Bus: Ticket already purchased for this trip");

        passengerCountPerTrip[currentTripId]++;
        hasTicketForTrip[currentTripId][msg.sender] = true;

        emit TicketPurchased(currentTripId, msg.sender);
    }

    /**
     * @dev Allows the owner to start the current trip.
     * Reverts if the trip is already in progress.
     */
    function startTrip() external onlyOwner {
        require(currentTripStatus == TripStatus.Stopped, "Bus: Trip is already in progress");
        currentTripStatus = TripStatus.InProgress;
        emit TripStarted(currentTripId);
    }

    /**
     * @dev Allows the owner to end the current trip.
     * This resets the bus to a 'Stopped' state and prepares for the next trip
     * by incrementing the trip ID, effectively clearing the passenger list for the new trip.
     * Reverts if a trip is not currently in progress.
     */
    function endTrip() external onlyOwner {
        require(currentTripStatus == TripStatus.InProgress, "Bus: Trip is not in progress");

        uint256 completedTripId = currentTripId;
        uint256 finalPassengerCount = passengerCountPerTrip[completedTripId];

        currentTripStatus = TripStatus.Stopped;
        currentTripId++;

        emit TripEnded(completedTripId, finalPassengerCount);
    }

    /**
     * @dev Allows the owner to withdraw the entire Ether balance of the contract.
     * Reverts if there are no funds to withdraw.
     */
    function withdraw() external onlyOwner nonReentrant {
        uint256 amount = address(this).balance;
        require(amount > 0, "Bus: No funds to withdraw");

        (bool success, ) = owner().call{value: amount}("");
        require(success, "Bus: Failed to send Ether");

        emit FundsWithdrawn(owner(), amount);
    }

    /**
     * @dev A view function to check if a specific address has a ticket for the current trip.
     * @param _passenger The address to check.
     * @return A boolean indicating if the address holds a valid ticket for the current trip.
     */
    function isCurrentPassenger(address _passenger) external view returns (bool) {
        return hasTicketForTrip[currentTripId][_passenger];
    }
}

